	event = tui.Invalid.AsEvent()
	if t.listenAddr == nil || t.listenAddr.IsLocal() || t.listenUnsafe {
		actions = serverActions
	} else {
		for _, action := range serverActions {
			if !processExecution(action.t) {
				actions = append(actions, action)
			}
		}
	}
